//! A tiny, dependency-free deterministic PRNG for fingerprint/persona
//! generation (plan §6; §14 "prefer std, few deps").
//!
//! Camio deliberately avoids the `rand` crate here: persona and user-agent
//! selection must be **reproducible from a seed** (so an identity can be pinned,
//! logged, and regenerated byte-for-byte), and the quality bar is "pick an item
//! from a weighted list without visible bias", not cryptographic randomness.
//! SplitMix64 is the standard, well-distributed choice for exactly this.
//!
//! This is NOT a CSPRNG. Do not use it for keys, tokens, or anything an
//! adversary must not predict — Camio's security-sensitive randomness lives
//! elsewhere (e.g. the OAST token minting uses OS entropy).

/// A SplitMix64 generator: seed in, a stream of well-mixed `u64`s out.
#[derive(Debug, Clone)]
pub struct SplitMix64 {
    state: u64,
}

impl SplitMix64 {
    /// Seed the generator. Any seed (including 0) gives a full-quality stream.
    pub fn new(seed: u64) -> Self {
        SplitMix64 { state: seed }
    }

    /// Seed from a best-effort "now + pid" mix for a one-off, non-reproducible
    /// identity. Callers that need reproducibility pass an explicit seed to
    /// [`SplitMix64::new`] instead.
    pub fn from_entropy() -> Self {
        let nanos = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_nanos() as u64)
            .unwrap_or(0);
        let pid = std::process::id() as u64;
        // Mix the two so two processes starting in the same nanosecond still
        // diverge, and a process restarting at the same pid still diverges.
        SplitMix64::new(nanos ^ pid.rotate_left(32))
    }

    /// Next raw 64-bit value.
    pub fn next_u64(&mut self) -> u64 {
        self.state = self.state.wrapping_add(0x9E3779B97F4A7C15);
        let mut z = self.state;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58476D1CE4E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D049BB133111EB);
        z ^ (z >> 31)
    }

    /// Uniform integer in `0..n` (returns 0 when `n == 0`). Uses the standard
    /// Lemire-style multiply-shift to avoid modulo bias for the small `n` these
    /// pools use.
    pub fn below(&mut self, n: u64) -> u64 {
        if n == 0 {
            return 0;
        }
        // 128-bit multiply, take the high word.
        ((self.next_u64() as u128 * n as u128) >> 64) as u64
    }

    /// Pick an index into `weights` with probability proportional to each
    /// weight. Returns 0 for an empty/all-zero slice (callers pass non-empty,
    /// positive-weight tables). O(n), fine for the small curated pools here.
    pub fn weighted_index(&mut self, weights: &[u32]) -> usize {
        let total: u64 = weights.iter().map(|&w| w as u64).sum();
        if total == 0 {
            return 0;
        }
        let mut pick = self.below(total);
        for (i, &w) in weights.iter().enumerate() {
            let w = w as u64;
            if pick < w {
                return i;
            }
            pick -= w;
        }
        weights.len() - 1
    }

    /// Pick a reference to a random element of `items` (weighted uniformly).
    /// Returns `None` only for an empty slice.
    pub fn choose<'a, T>(&mut self, items: &'a [T]) -> Option<&'a T> {
        if items.is_empty() {
            return None;
        }
        let i = self.below(items.len() as u64) as usize;
        items.get(i)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn deterministic_from_seed() {
        let mut a = SplitMix64::new(42);
        let mut b = SplitMix64::new(42);
        for _ in 0..100 {
            assert_eq!(a.next_u64(), b.next_u64());
        }
    }

    #[test]
    fn different_seeds_diverge() {
        let mut a = SplitMix64::new(1);
        let mut b = SplitMix64::new(2);
        assert_ne!(a.next_u64(), b.next_u64());
    }

    #[test]
    fn below_is_in_range() {
        let mut r = SplitMix64::new(7);
        for _ in 0..1000 {
            assert!(r.below(10) < 10);
        }
        assert_eq!(r.below(0), 0);
        assert_eq!(r.below(1), 0);
    }

    #[test]
    fn weighted_index_respects_weights() {
        // Weight [0, 100, 0] must always pick index 1.
        let mut r = SplitMix64::new(3);
        for _ in 0..50 {
            assert_eq!(r.weighted_index(&[0, 100, 0]), 1);
        }
        // Roughly proportional for [1, 3].
        let mut r = SplitMix64::new(99);
        let mut ones = 0;
        for _ in 0..4000 {
            if r.weighted_index(&[1, 3]) == 0 {
                ones += 1;
            }
        }
        // Expect ~25% index-0; allow a wide band so the test is not flaky.
        assert!(ones > 700 && ones < 1300, "got {ones} of 4000");
    }

    #[test]
    fn choose_handles_empty_and_nonempty() {
        let mut r = SplitMix64::new(5);
        let empty: [u32; 0] = [];
        assert!(r.choose(&empty).is_none());
        let items = [10, 20, 30];
        assert!(items.contains(r.choose(&items).unwrap()));
    }
}
